"""
Git pre-commit hook installer and manager.
"""

import os
from pathlib import Path
import stat
from typing import Union

HOOK_SCRIPT = """#!/usr/bin/env bash
# secret-leak-guard pre-commit hook
# Automatically generated by secret-leak-guard

echo "🔒 Running secret-leak-guard pre-commit scan on staged files..."

if command -v secret-leak-guard >/dev/null 2>&1; then
    secret-leak-guard diff --staged --fail-on-findings
elif python -m secret_leak_guard.cli --version >/dev/null 2>&1; then
    python -m secret_leak_guard.cli diff --staged --fail-on-findings
elif python3 -m secret_leak_guard.cli --version >/dev/null 2>&1; then
    python3 -m secret_leak_guard.cli diff --staged --fail-on-findings
else
    echo "⚠️ secret-leak-guard is not installed in the active environment. Skipping."
    exit 0
fi

EXIT_CODE=$?
if [ $EXIT_CODE -ne 0 ]; then
    echo ""
    echo "❌ COMMIT BLOCKED: Accidental secrets or tokens detected in staged diff!"
    echo "   Please remove the secrets, or use inline suppression:"
    echo "   '# pragma: allowlist secret' or '# nosecret'"
    echo "   To bypass intentionally (emergency only): git commit --no-verify"
    exit $EXIT_CODE
fi

exit 0
"""


def install_git_hook(repo_root: Union[str, Path] = ".") -> bool:
    """Installs the pre-commit hook in .git/hooks/pre-commit."""
    git_dir = Path(repo_root) / ".git"
    if not git_dir.exists() or not git_dir.is_dir():
        raise RuntimeError(f"Directory '{repo_root}' is not the root of a Git repository (.git not found).")

    hooks_dir = git_dir / "hooks"
    hooks_dir.mkdir(parents=True, exist_ok=True)
    hook_file = hooks_dir / "pre-commit"

    hook_file.write_text(HOOK_SCRIPT, encoding="utf-8")

    # Set executable permissions (non-Windows / POSIX)
    try:
        current_stat = hook_file.stat()
        hook_file.chmod(current_stat.st_mode | stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH)
    except Exception:
        pass

    return True


def uninstall_git_hook(repo_root: Union[str, Path] = ".") -> bool:
    """Removes the pre-commit hook if installed by secret-leak-guard."""
    hook_file = Path(repo_root) / ".git" / "hooks" / "pre-commit"
    if hook_file.exists():
        content = hook_file.read_text(encoding="utf-8", errors="replace")
        if "secret-leak-guard" in content:
            hook_file.unlink()
            return True
        else:
            raise RuntimeError("pre-commit hook exists but was not created by secret-leak-guard.")
    return False
